//! Keccak-256 of the RV64 guest: a sponge around a Keccak-f[1600] written in assembly.
//!
//! The guest is an RV64I + Zmmul machine with aligned loads and stores only, and its cost is the
//! number of executed instructions. The permutation keeps the 25 lanes in registers for all 24
//! unrolled rounds: `keccak_f1600_rv64_ops.S` with binbender's Keccak opcodes (generated by
//! `keccak_f1600_rv64_ops_gen.py`), or without them `keccak_f1600_rv64.S` (generated by
//! `keccak_f1600_rv64_gen.py`), which has no rotation and no and-not. The sponge here absorbs straight into the
//! state, by words of the input wherever the input is word-aligned.
//!
//! Nothing is zeroed when a hasher is created or reset: the state says how many of its lanes
//! are initialised (see [`Keccak256Core`]). Until the first permutation the lanes hold the
//! message as it is, and a short hash (at most 64 bytes, most of what a block hashes) never
//! becomes a full state: the assembly takes its nine lanes and knows the rest are zero. After
//! the first permutation the state is in the representation of the lane-complementing
//! transform, which the rounds work in: the lanes of [`COMPLEMENTED_LANES`] are stored
//! complemented. The last permutation of a hash computes and stores only the digest.
//!
//! The sponge is generic over the permutation ([`KeccakF1600`]), so that the host tests run it
//! with a software permutation (under Miri too, which sees a read of a lane that was never
//! written); the guest uses [`Assembly`].

use crate::{Bytes32, MiniDigest};
use core::marker::PhantomData;
use core::mem::MaybeUninit;

#[cfg(not(target_endian = "little"))]
compile_error!("the sponge reads the input and the state as little-endian words");

const LANES: usize = 25;
/// The rate of Keccak-256 in bytes and in lanes
const RATE: usize = 136;
const RATE_WORDS: usize = RATE / 8;
/// A message of at most this many bytes, with its padding byte, lies in [`SHORT_LANES`] lanes
const SHORT_BYTES: usize = 64;
const SHORT_LANES: usize = SHORT_BYTES / 8 + 1;

/// Bit `i` is set when lane `i` (`x + 5 y`) of the state is stored complemented. It must be the
/// set that `keccak_f1600_rv64.S` was generated for (its header names the lanes).
#[cfg(not(feature = "keccak_call"))]
pub const COMPLEMENTED_LANES: u32 = 1 << 3 | 1 << 7 | 1 << 8 | 1 << 12 | 1 << 17 | 1 << 23;
/// `call.keccak` permutes the plain state: no lane is complemented.
#[cfg(feature = "keccak_call")]
pub const COMPLEMENTED_LANES: u32 = 0;

const fn complement_of(lane: usize) -> u64 {
    if COMPLEMENTED_LANES >> lane & 1 == 1 {
        !0
    } else {
        0
    }
}

/// Keccak-f[1600] over a state stored with the lanes of [`COMPLEMENTED_LANES`] complemented,
/// and the entries for a state that no permutation has touched yet.
pub trait KeccakF1600 {
    /// `state <- f(state)`
    fn permute(state: &mut [u64; LANES]);

    /// `blocks` times: xor the next 17 words of `data` into lanes 0-16, then `f`.
    ///
    /// # Safety
    /// `data` must be aligned and valid for reads of `17 * blocks` words, and `blocks >= 1`.
    unsafe fn absorb_blocks(state: &mut [u64; LANES], data: *const u64, blocks: usize);

    /// The same from the all-zero Keccak state: `state` is written, never read.
    ///
    /// # Safety
    /// As [`Self::absorb_blocks`]; `state` must be aligned and valid for writes of 25 words.
    unsafe fn absorb_first(state: *mut [u64; LANES], data: *const u64, blocks: usize);

    /// The last permutation of a hash: writes lanes 0-3 of `f(state)` to `digest`, plain (no
    /// lane complemented). The rest of `f(state)` is dropped, and the state is unspecified
    /// afterwards. `digest` may be the start of `state`.
    ///
    /// # Safety
    /// `state` must be aligned and valid for reads and writes of 25 words (an implementation may
    /// permute it in place), `digest` for writes of 4 words.
    unsafe fn squeeze(state: *mut [u64; LANES], digest: *mut [u64; 4]);

    /// A whole hash of at most 64 bytes. `lanes` are the first nine lanes of its only block,
    /// plain: the message, the padding byte `0x01`, zeros. The final padding bit and the zero
    /// lanes are implied. Writes the digest; `digest` may be `lanes`.
    ///
    /// # Safety
    /// `lanes` must be aligned and valid for reads of 9 words, `digest` for writes of 4 words.
    unsafe fn squeeze_short(lanes: *const [u64; SHORT_LANES], digest: *mut [u64; 4]);
}

#[cfg(all(target_arch = "riscv64", not(feature = "keccak_call")))]
mod assembly {
    use super::{KeccakF1600, LANES, SHORT_LANES};

    // SAFETY: the routines are leaf functions of the C calling convention. They save and restore
    // `ra`, `gp`, `tp` and `s0`-`s11` in a 144-byte frame below the entry `sp` (which stays
    // 16-byte aligned), clobber the caller-saved registers only, and touch no memory but that
    // frame, the state, the absorbed words, the digest and their table of round constants.
    // Nothing can observe `gp` and `tp` while they hold lanes: the guest has no interrupts and
    // no threads. `keccak_f1600_rv64_ops.S` (binbender's XRI, RAX1, BCAX and EOR3) has the
    // entries, contracts and frame of `keccak_f1600_rv64.S`, whose header states them.
    core::arch::global_asm!(include_str!("keccak_f1600_rv64_ops.S"), options(raw));

    extern "C" {
        fn airbender_keccak_f1600_rv64(state: *mut [u64; LANES]);
        fn airbender_keccak_f1600_rv64_absorb(
            state: *mut [u64; LANES],
            data: *const u64,
            blocks: usize,
        );
        fn airbender_keccak_f1600_rv64_absorb_first(
            state: *mut [u64; LANES],
            data: *const u64,
            blocks: usize,
        );
        fn airbender_keccak_f1600_rv64_final(state: *const [u64; LANES], digest: *mut [u64; 4]);
        fn airbender_keccak_f1600_rv64_final64(
            lanes: *const [u64; SHORT_LANES],
            digest: *mut [u64; 4],
        );
    }

    /// The permutation of `keccak_f1600_rv64.S`
    #[derive(Clone, Copy, Debug, Default)]
    pub struct Assembly;

    impl KeccakF1600 for Assembly {
        #[inline(always)]
        fn permute(state: &mut [u64; LANES]) {
            // SAFETY: `state` is valid for reads and writes of 25 aligned words.
            unsafe { airbender_keccak_f1600_rv64(state) }
        }

        #[inline(always)]
        unsafe fn absorb_blocks(state: &mut [u64; LANES], data: *const u64, blocks: usize) {
            debug_assert!(blocks >= 1 && data.is_aligned());
            // SAFETY: `state` as above; the caller vouches for `data` and `blocks`, and a
            // shared borrow of the input cannot overlap the exclusively borrowed state.
            unsafe { airbender_keccak_f1600_rv64_absorb(state, data, blocks) }
        }

        #[inline(always)]
        unsafe fn absorb_first(state: *mut [u64; LANES], data: *const u64, blocks: usize) {
            debug_assert!(blocks >= 1 && data.is_aligned());
            // SAFETY: the caller's contract is the one of the routine, which stores the 25
            // lanes and loads none of them.
            unsafe { airbender_keccak_f1600_rv64_absorb_first(state, data, blocks) }
        }

        #[inline(always)]
        unsafe fn squeeze(state: *mut [u64; LANES], digest: *mut [u64; 4]) {
            // SAFETY: the caller's contract is the one of the routine, which loads the whole
            // state before it stores the digest: the two may overlap.
            unsafe { airbender_keccak_f1600_rv64_final(state, digest) }
        }

        #[inline(always)]
        unsafe fn squeeze_short(lanes: *const [u64; SHORT_LANES], digest: *mut [u64; 4]) {
            // SAFETY: the caller's contract is the one of the routine, which loads the nine
            // lanes, and no other word, before it stores the digest.
            unsafe { airbender_keccak_f1600_rv64_final64(lanes, digest) }
        }
    }
}

#[cfg(all(target_arch = "riscv64", not(feature = "keccak_call")))]
pub use self::assembly::Assembly;

/// The permutation as binbender's `call.keccak` (github.com/matter-labs/binbender,
/// crates/machine/src/isa.rs, `Opcode::Call(Table::Keccak)`): custom-2 (0x5b), funct3 0,
/// rd = x0, imm = 0. It permutes in place the 25 plain lanes at `rs1`, lane `x + 5 y` the
/// little-endian doubleword at `rs1 + 8 (x + 5 y)`.
#[cfg(all(target_arch = "riscv64", feature = "keccak_call"))]
mod call {
    use super::{KeccakF1600, LANES, RATE_WORDS, SHORT_LANES};

    /// # Safety
    /// `state` must be aligned and valid for reads and writes of 25 words.
    #[inline(always)]
    unsafe fn keccak_f(state: *mut [u64; LANES]) {
        // SAFETY: the caller's contract. The call reads and writes those 25 words and no other
        // memory or register.
        unsafe {
            core::arch::asm!(".insn i 0x5b, 0, x0, {0}, 0", in(reg) state, options(nostack));
        }
    }

    /// Keccak-f[1600] through `call.keccak`
    #[derive(Clone, Copy, Debug, Default)]
    pub struct Assembly;

    impl KeccakF1600 for Assembly {
        #[inline(always)]
        fn permute(state: &mut [u64; LANES]) {
            // SAFETY: a unique reference to 25 aligned words.
            unsafe { keccak_f(state) }
        }

        #[inline(always)]
        unsafe fn absorb_blocks(state: &mut [u64; LANES], data: *const u64, blocks: usize) {
            for block in 0..blocks {
                for lane in 0..RATE_WORDS {
                    // SAFETY: the caller's contract: `data` holds `17 * blocks` aligned words.
                    state[lane] ^= unsafe { data.add(block * RATE_WORDS + lane).read() };
                }
                // SAFETY: a unique reference to 25 aligned words.
                unsafe { keccak_f(state) };
            }
        }

        #[inline(always)]
        unsafe fn absorb_first(state: *mut [u64; LANES], data: *const u64, blocks: usize) {
            // SAFETY: the caller's contract: `state` is valid for writes of 25 aligned words and
            // `data` for reads of `17 * blocks`.
            unsafe {
                let lanes = state.cast::<u64>();
                for lane in 0..RATE_WORDS {
                    lanes.add(lane).write(data.add(lane).read());
                }
                for lane in RATE_WORDS..LANES {
                    lanes.add(lane).write(0);
                }
                keccak_f(state);
                if blocks > 1 {
                    Self::absorb_blocks(&mut *state, data.add(RATE_WORDS), blocks - 1);
                }
            }
        }

        #[inline(always)]
        unsafe fn squeeze(state: *mut [u64; LANES], digest: *mut [u64; 4]) {
            // SAFETY: the caller's contract, which lets the state be permuted in place. `digest`
            // may start at `state`: the lanes are copied in order.
            unsafe {
                keccak_f(state);
                for lane in 0..4 {
                    digest.cast::<u64>().add(lane).write(state.cast::<u64>().add(lane).read());
                }
            }
        }

        #[inline(always)]
        unsafe fn squeeze_short(lanes: *const [u64; SHORT_LANES], digest: *mut [u64; 4]) {
            let mut state = [0u64; LANES];
            // SAFETY: the caller's contract: nine aligned words to read.
            state[..SHORT_LANES].copy_from_slice(unsafe { &*lanes });
            state[RATE_WORDS - 1] ^= 1 << 63;
            // SAFETY: a local array of 25 words.
            unsafe { keccak_f(&mut state) };
            // SAFETY: the caller's contract: four aligned words to write.
            unsafe { digest.write(state[..4].try_into().unwrap()) };
        }
    }
}

#[cfg(all(target_arch = "riscv64", feature = "keccak_call"))]
pub use self::call::Assembly;

/// Keccak-256 with the permutation of `keccak_f1600_rv64.S`
#[cfg(target_arch = "riscv64")]
pub type Keccak256 = Keccak256Core<Assembly>;

/// Keccak-f[1600] of the assembly over the lanes as stored: those of [`COMPLEMENTED_LANES`]
/// complemented on entry and on return.
#[cfg(target_arch = "riscv64")]
#[inline(always)]
pub fn keccak_f1600_complemented(state: &mut [u64; LANES]) {
    Assembly::permute(state)
}

/// Keccak-f[1600] of the assembly over a plain state.
#[cfg(target_arch = "riscv64")]
pub fn keccak_f1600(state: &mut [u64; LANES]) {
    for (lane, word) in state.iter_mut().enumerate() {
        *word ^= complement_of(lane);
    }
    Assembly::permute(state);
    for (lane, word) in state.iter_mut().enumerate() {
        *word ^= complement_of(lane);
    }
}

/// `dst[i] = src[i]` for `len` words, four at a time: no loop counter per word, and no
/// `memcpy` call.
///
/// # Safety
/// `src` must be aligned and valid for reads of `len` words, `dst` for writes.
#[inline(always)]
unsafe fn copy_words(mut dst: *mut u64, mut src: *const u64, mut len: usize) {
    // SAFETY: every access is below `len` words from the pointers the caller vouches for.
    unsafe {
        while len >= 4 {
            seq_macro::seq!(N in 0..4 {
                dst.add(N).write_volatile(src.add(N).read());
            });
            dst = dst.add(4);
            src = src.add(4);
            len -= 4;
        }
        if len & 2 != 0 {
            seq_macro::seq!(N in 0..2 {
                dst.add(N).write_volatile(src.add(N).read());
            });
            dst = dst.add(2);
            src = src.add(2);
        }
        if len & 1 != 0 {
            dst.write_volatile(src.read());
        }
    }
}

/// `dst[i] ^= src[i]` for `len` words, four at a time.
///
/// # Safety
/// `dst` and `src` must be aligned and valid for `len` words, those of `dst` initialised.
#[inline(always)]
unsafe fn xor_words(mut dst: *mut u64, mut src: *const u64, mut len: usize) {
    // SAFETY: every access is below `len` words from the pointers the caller vouches for.
    unsafe {
        while len >= 4 {
            seq_macro::seq!(N in 0..4 {
                dst.add(N).write(dst.add(N).read() ^ src.add(N).read());
            });
            dst = dst.add(4);
            src = src.add(4);
            len -= 4;
        }
        if len & 2 != 0 {
            seq_macro::seq!(N in 0..2 {
                dst.add(N).write(dst.add(N).read() ^ src.add(N).read());
            });
            dst = dst.add(2);
            src = src.add(2);
        }
        if len & 1 != 0 {
            dst.write(dst.read() ^ src.read());
        }
    }
}

/// The `len < 8` bytes at a word-aligned `src` as the low bytes of a word: a four-byte, a
/// two-byte and a one-byte load as the bits of `len` say, each naturally aligned.
///
/// # Safety
/// `src` must be valid for reads of `len` bytes and, unless `len` is 0, aligned to 8.
#[inline(always)]
unsafe fn tail_word(src: *const u8, len: usize) -> u64 {
    debug_assert!(len < 8 && (len == 0 || src as usize % 8 == 0));
    let mut word = 0u64;
    let mut at = 0;
    // SAFETY: the loads cover bytes `0..len`; offsets 0 and 4 from a word-aligned address are
    // aligned for two bytes, offset 0 for four.
    unsafe {
        if len & 4 != 0 {
            word = src.cast::<u32>().read() as u64;
            at = 4;
        }
        if len & 2 != 0 {
            word |= (src.add(at).cast::<u16>().read() as u64) << (8 * at);
            at += 2;
        }
        if len & 1 != 0 {
            word |= (src.add(at).read() as u64) << (8 * at);
        }
    }
    word
}

/// Xors `len` words of `src` into `dst` at a bit offset of `shift` (8, 16, .. 56): word `i`
/// lands on the high part of `dst[i]` and the low part of `dst[i + 1]`. Returns the part of the
/// last word that belongs to `dst[len]`, which the caller places. Four words at a time, as
/// `xor_words`.
///
/// # Safety
/// `dst` and `src` must be aligned and valid for `len` words, those of `dst` initialised.
#[inline(always)]
unsafe fn xor_words_shifted(
    mut dst: *mut u64,
    mut src: *const u64,
    mut len: usize,
    shift: u32,
) -> u64 {
    debug_assert!(shift % 8 == 0 && shift > 0 && shift < 64);
    let back = 64 - shift;
    let mut carry = 0u64;
    // SAFETY: every access is below `len` words from the pointers the caller vouches for.
    unsafe {
        while len >= 4 {
            seq_macro::seq!(N in 0..4 {
                let word = src.add(N).read();
                dst.add(N).write(dst.add(N).read() ^ (word << shift | carry));
                carry = word >> back;
            });
            dst = dst.add(4);
            src = src.add(4);
            len -= 4;
        }
        while len > 0 {
            let word = src.read();
            dst.write(dst.read() ^ (word << shift | carry));
            carry = word >> back;
            dst = dst.add(1);
            src = src.add(1);
            len -= 1;
        }
    }
    carry
}

/// `valid` of a state that a permutation has produced
const STORED: usize = LANES;

/// Keccak-256 (rate 136, padding `0x01 .. 0x80`) over the permutation `F`.
///
/// Creating or resetting a hasher writes two counters and no lane. Which lanes of `state` are
/// initialised, and what they mean, follows from `valid`:
///
/// * `valid <= 17`, a *fresh* state: no permutation has run since the hasher was created or
///   reset. Lanes `0..valid` are initialised and hold the bytes absorbed so far, plain,
///   followed by zero bytes; the lanes from `valid` on are NOT initialised and stand for zero.
///   `valid` is either `ceil(filled / 8)`, the lanes the message has reached, or 17 once the
///   whole rate has been zero-filled (a piece arrived unaligned or in the middle of a lane).
/// * `valid == 25` ([`STORED`]): all 25 lanes are initialised, in the representation of the
///   rounds (the lanes of [`COMPLEMENTED_LANES`] complemented).
///
/// A lane at or above `valid` is never read: it is first written, by a store of the absorbed
/// word, by the padding, by a zero-fill up to the lanes an entry of the permutation takes, or
/// by the permutation itself.
pub struct Keccak256Core<F: KeccakF1600> {
    state: [MaybeUninit<u64>; LANES],
    /// Bytes absorbed into the current block: always below [`RATE`]
    filled: usize,
    /// See the type
    valid: usize,
    permutation: PhantomData<F>,
}

impl<F: KeccakF1600> Keccak256Core<F> {
    /// Same as [`MiniDigest::new`], for a hasher in a `static` or a `const`.
    pub const fn const_new() -> Self {
        Self {
            state: [MaybeUninit::uninit(); LANES],
            filled: 0,
            valid: 0,
            permutation: PhantomData,
        }
    }

    /// The digest, computed in place: the hasher must be reset before it is used again
    /// ([`MiniDigest::finalize_reset`] does both).
    #[inline(always)]
    pub fn finalize_in_place(&mut self) -> Bytes32 {
        let mut digest = MaybeUninit::<Bytes32>::uninit();
        // SAFETY: `Bytes32` is 32 bytes aligned to a word, which `finish` writes; the machine
        // is little-endian, so the four lanes are the bytes of the digest.
        unsafe {
            self.finish(Some(digest.as_mut_ptr().cast::<[u64; 4]>()));
            digest.assume_init()
        }
    }

    #[inline(always)]
    fn reset(&mut self) {
        self.filled = 0;
        self.valid = 0;
    }

    #[inline(always)]
    fn lanes(&mut self) -> *mut u64 {
        self.state.as_mut_ptr().cast::<u64>()
    }

    /// Zero-fills the rate of a fresh state, so that every lane of the rate can be xored
    /// into. Nothing to do on a stored state.
    #[inline(always)]
    fn fill_rate(&mut self) {
        let mut lane = self.valid;
        // SAFETY: lanes below 17. Volatile, or the loop is recognised as a `memset` and
        // becomes a call that costs more than the stores.
        unsafe {
            while lane < RATE_WORDS {
                self.lanes().add(lane).write_volatile(0);
                lane += 1;
            }
        }
        if self.valid < RATE_WORDS {
            self.valid = RATE_WORDS;
        }
    }

    /// Turns a fresh state into a stored one: the rate zero-filled and its complemented lanes
    /// complemented, the capacity written.
    #[inline(never)]
    fn make_stored(&mut self) {
        debug_assert!(self.valid <= RATE_WORDS);
        self.fill_rate();
        let lanes = self.lanes();
        // SAFETY: the 17 lanes of the rate are initialised now, the other 8 are written.
        unsafe {
            seq_macro::seq!(N in 0..17 {
                if complement_of(N) != 0 {
                    lanes.add(N).write(!lanes.add(N).read());
                }
            });
            seq_macro::seq!(N in 17..25 {
                lanes.add(N).write(complement_of(N));
            });
        }
        self.valid = STORED;
    }

    /// Pads and writes the digest, to `digest` or else over the first four lanes of the
    /// state. The rest of the state is unspecified afterwards.
    ///
    /// # Safety
    /// `digest`, if given, must be aligned and valid for writes of 4 words.
    #[inline(always)]
    unsafe fn finish(&mut self, digest: Option<*mut [u64; 4]>) {
        let filled = self.filled;
        debug_assert!(filled < RATE);
        if self.valid != STORED {
            if filled <= SHORT_BYTES {
                // A fresh state of at most 64 bytes: the hash is one permutation of nine
                // plain lanes.
                let lane = filled / 8;
                let lanes = self.lanes();
                // SAFETY: `lane < 9`. If `valid == lane` the message ends at the boundary of
                // a lane that is not initialised, and the padding byte is that lane;
                // otherwise lane `lane` is initialised (`valid > lane`) and takes the byte.
                // The lanes from `valid` to 8 are then written, so nine are initialised.
                unsafe {
                    if self.valid == lane {
                        lanes.add(lane).write(0x01);
                        self.valid = lane + 1;
                    } else {
                        let byte = lanes.cast::<u8>().add(filled);
                        *byte ^= 0x01;
                    }
                    let mut next = self.valid;
                    while next < SHORT_LANES {
                        lanes.add(next).write_volatile(0);
                        next += 1;
                    }
                    let digest = digest.unwrap_or(lanes.cast::<[u64; 4]>());
                    F::squeeze_short(lanes.cast::<[u64; SHORT_LANES]>(), digest);
                }
                return;
            }
            self.make_stored();
        }
        let lanes = self.lanes();
        // SAFETY: the state is stored: 25 initialised lanes. `filled` and `RATE - 1` are byte
        // offsets inside it; the lanes are little-endian, so byte `i` of the rate is byte `i`
        // of the state.
        unsafe {
            let bytes = lanes.cast::<u8>();
            *bytes.add(filled) ^= 0x01;
            *bytes.add(RATE - 1) ^= 0x80;
            let digest = digest.unwrap_or(lanes.cast::<[u64; 4]>());
            F::squeeze(lanes.cast::<[u64; LANES]>(), digest);
        }
    }

    /// The common case of `update`, without a call: the block stays open, and the source is
    /// word-aligned at a lane boundary of the block. On a fresh state the words are stored,
    /// not xored. The other shapes are out of line.
    #[inline(always)]
    fn absorb(&mut self, input: &[u8]) {
        let src = input.as_ptr();
        let len = input.len();
        let filled = self.filled;
        if len >= RATE - filled {
            return self.absorb_closing(input);
        }
        if (src as usize | filled) % 8 != 0 {
            return self.absorb_open(input);
        }
        let lane = filled / 8;
        let words = len / 8;
        let rest = len % 8;
        // SAFETY: `src` is aligned and valid for `words` words and the `rest` bytes after
        // them; `filled + len < RATE`, so the lanes from `lane` on that the words and the
        // rest reach are inside the rate. If `valid == lane` the state is fresh and those
        // lanes are not initialised: they are written. Otherwise `valid > lane` with
        // `filled` a multiple of 8, which by the invariant of the type means the whole rate
        // is initialised (`valid` is 17 or 25), and they are xored into.
        unsafe {
            let dst = self.lanes().add(lane);
            let tail = src.add(len - rest);
            if self.valid == lane {
                copy_words(dst, src.cast::<u64>(), words);
                if rest != 0 {
                    dst.add(words).write(tail_word(tail, rest));
                }
                self.valid = lane + words + (rest != 0) as usize;
            } else {
                debug_assert!(self.valid >= RATE_WORDS);
                xor_words(dst, src.cast::<u64>(), words);
                let last = dst.add(words);
                if rest != 0 {
                    last.write(last.read() ^ tail_word(tail, rest));
                }
            }
        }
        self.filled = filled + len;
    }

    /// A piece that leaves the block open but is not word-aligned at a lane boundary: bytes
    /// until the source is aligned, words of the source (shifted if the block is then in the
    /// middle of a lane), the rest by bytes. No permutation: a leaf.
    #[inline(never)]
    fn absorb_open(&mut self, input: &[u8]) {
        self.fill_rate();
        let mut src = input.as_ptr();
        let mut len = input.len();
        let mut filled = self.filled;
        debug_assert!(len < RATE - filled);
        // SAFETY: the rate is initialised (`fill_rate`), and every byte and lane touched is
        // below `filled + len < RATE`: the carry of the shifted words ends before the byte
        // `filled + 8 * words`. The three parts cover the `len` bytes of `input`, the middle
        // one from a word-aligned address.
        unsafe {
            let lanes = self.lanes();
            let bytes = lanes.cast::<u8>();
            let head = core::cmp::min((src as usize).wrapping_neg() % 8, len);
            let end = src.add(head);
            while src != end {
                *bytes.add(filled) ^= *src;
                src = src.add(1);
                filled += 1;
            }
            len -= head;
            let words = len / 8;
            let dst = lanes.add(filled / 8);
            let shift = (filled % 8) as u32 * 8;
            if shift == 0 {
                xor_words(dst, src.cast::<u64>(), words);
            } else if words != 0 {
                let carry = xor_words_shifted(dst, src.cast::<u64>(), words, shift);
                let last = dst.add(words);
                last.write(last.read() ^ carry);
            }
            src = src.add(words * 8);
            filled += words * 8;
            let end = src.add(len % 8);
            while src != end {
                *bytes.add(filled) ^= *src;
                src = src.add(1);
                filled += 1;
            }
        }
        self.filled = filled;
    }

    /// A piece that completes at least one block.
    #[inline(always)]
    fn absorb_closing(&mut self, input: &[u8]) {
        if self.valid != STORED && self.filled == 0 && input.as_ptr() as usize % 8 == 0 {
            self.absorb_blocks_fresh(input)
        } else {
            self.absorb_closing_general(input)
        }
    }

    /// Whole blocks of an aligned source into a fresh, empty state: the assembly loads the
    /// first block instead of xoring it into zeros, and leaves a stored state. The rest is
    /// less than a block.
    #[inline(never)]
    fn absorb_blocks_fresh(&mut self, input: &[u8]) {
        let mut src = input.as_ptr();
        let mut len = input.len();
        debug_assert!(self.valid == 0 && self.filled == 0 && len >= RATE);
        // SAFETY: `src` is aligned and valid for `len >= RATE` bytes: `blocks` blocks and
        // then `len` more. `absorb_first` writes the 25 lanes, which are xored into after.
        unsafe {
            let blocks = len / RATE;
            F::absorb_first(self.state.as_mut_ptr().cast(), src.cast::<u64>(), blocks);
            self.valid = STORED;
            src = src.add(blocks * RATE);
            len -= blocks * RATE;
            let lanes = self.lanes();
            xor_words(lanes, src.cast::<u64>(), len / 8);
            let last = lanes.add(len / 8);
            if len % 8 != 0 {
                last.write(last.read() ^ tail_word(src.add(len & !7), len % 8));
            }
        }
        self.filled = len;
    }

    /// Any other piece that completes a block: on a stored state, which a fresh one is turned
    /// into first.
    #[inline(never)]
    fn absorb_closing_general(&mut self, input: &[u8]) {
        let mut src = input.as_ptr();
        let mut len = input.len();
        if self.valid != STORED {
            self.make_stored();
        }
        let mut filled = self.filled;
        // SAFETY: the state is stored, so its 25 lanes are initialised. The three parts are
        // consecutive and cover the `len` bytes of `input`; the middle one starts at a
        // word-aligned address. `filled < RATE` throughout.
        unsafe {
            let state = &mut *self.state.as_mut_ptr().cast::<[u64; LANES]>();
            let head = core::cmp::min((src as usize).wrapping_neg() % 8, len);
            filled = Self::absorb_bytes(state, filled, src, head);
            src = src.add(head);
            len -= head;
            let rest = src.add(len & !7);
            if filled % 8 == 0 {
                let lane = Self::absorb_lanes(state, filled / 8, src.cast::<u64>(), len / 8);
                // less than a word at a lane boundary: inside the rate, the block stays open
                let last = state.as_mut_ptr().add(lane);
                if len % 8 != 0 {
                    last.write(last.read() ^ tail_word(rest, len % 8));
                }
                filled = lane * 8 + len % 8;
            } else {
                filled = Self::absorb_shifted(state, filled, src.cast::<u64>(), len / 8);
                filled = Self::absorb_bytes(state, filled, rest, len % 8);
            }
        }
        self.filled = filled;
    }

    /// Absorbs `len` bytes one by one at byte `filled` of the block of a stored state. Returns
    /// the bytes in the block afterwards.
    ///
    /// # Safety
    /// `src` must be valid for reads of `len` bytes, and `filled < RATE`.
    #[inline(always)]
    unsafe fn absorb_bytes(
        state: &mut [u64; LANES],
        mut filled: usize,
        mut src: *const u8,
        len: usize,
    ) -> usize {
        // SAFETY: `filled < RATE` indexes a byte of the state; `src` stays below `len`.
        unsafe {
            let end = src.add(len);
            while src != end {
                let dst = state.as_mut_ptr().cast::<u8>().add(filled);
                *dst ^= *src;
                src = src.add(1);
                filled += 1;
                if filled == RATE {
                    F::permute(state);
                    filled = 0;
                }
            }
        }
        filled
    }

    /// Absorbs `words` words of an aligned source at lane `lane` of the block of a stored
    /// state: a word of the source is a lane. Returns the lane after them.
    ///
    /// # Safety
    /// `src` must be aligned and valid for reads of `words` words, and `lane < RATE_WORDS`.
    #[inline(always)]
    unsafe fn absorb_lanes(
        state: &mut [u64; LANES],
        mut lane: usize,
        mut src: *const u64,
        mut words: usize,
    ) -> usize {
        // SAFETY: the xors stay inside the rate, as noted; `src` advances by the words read.
        unsafe {
            if lane != 0 {
                // up to the end of the block
                let take = core::cmp::min(words, RATE_WORDS - lane);
                xor_words(state.as_mut_ptr().add(lane), src, take);
                lane += take;
                if lane != RATE_WORDS {
                    return lane; // the source ended first
                }
                src = src.add(take);
                words -= take;
                F::permute(state);
            }
            if words >= RATE_WORDS {
                // whole blocks: xored into the lanes while they are in registers
                let blocks = words / RATE_WORDS;
                F::absorb_blocks(state, src, blocks);
                src = src.add(blocks * RATE_WORDS);
                words -= blocks * RATE_WORDS;
            }
            xor_words(state.as_mut_ptr(), src, words);
        }
        words
    }

    /// Absorbs `words` words of an aligned source at byte `filled` of the block of a stored
    /// state, which is not a multiple of 8: a word of the source covers the high bytes of one
    /// lane and the low bytes of the next. Returns the bytes in the block afterwards.
    ///
    /// # Safety
    /// `src` must be aligned and valid for reads of `words` words, and `filled < RATE`.
    #[inline(always)]
    unsafe fn absorb_shifted(
        state: &mut [u64; LANES],
        mut filled: usize,
        mut src: *const u64,
        mut words: usize,
    ) -> usize {
        let shift = (filled % 8) as u32 * 8;
        debug_assert!(shift != 0);
        // SAFETY: `take` words starting inside lane `lane` end inside lane 16 at most, the last
        // lane of the rate; `src` advances by the words read.
        unsafe {
            while words > 0 {
                let lane = filled / 8;
                let take = core::cmp::min(words, RATE_WORDS - 1 - lane);
                let dst = state.as_mut_ptr().add(lane);
                let carry = xor_words_shifted(dst, src, take, shift);
                src = src.add(take);
                words -= take;
                filled += take * 8;
                let last = dst.add(take);
                if words > 0 {
                    // `last` is lane 16: this word fills the block and opens the next one
                    let word = src.read();
                    last.write(last.read() ^ (word << shift | carry));
                    F::permute(state);
                    state[0] ^= word >> (64 - shift);
                    filled = shift as usize / 8;
                    src = src.add(1);
                    words -= 1;
                } else {
                    last.write(last.read() ^ carry);
                }
            }
        }
        filled
    }

    #[inline(never)]
    fn update_slice(&mut self, input: &[u8]) {
        self.absorb(input);
    }

    #[inline(never)]
    fn digest_slice(input: &[u8]) -> Bytes32 {
        let mut hasher = Self::const_new();
        hasher.absorb(input);
        hasher.finalize_in_place()
    }
}

impl<F: KeccakF1600> MiniDigest for Keccak256Core<F> {
    type HashOutput = Bytes32;

    /// Two counters: no lane is written.
    #[inline(always)]
    fn new() -> Self {
        Self::const_new()
    }

    #[inline(always)]
    fn digest(input: impl AsRef<[u8]>) -> Self::HashOutput {
        Self::digest_slice(input.as_ref())
    }

    #[inline(always)]
    fn update(&mut self, input: impl AsRef<[u8]>) {
        self.update_slice(input.as_ref());
    }

    #[inline(always)]
    fn finalize(mut self) -> Self::HashOutput {
        self.finalize_in_place()
    }

    #[inline(always)]
    fn finalize_reset(&mut self) -> Self::HashOutput {
        let output = self.finalize_in_place();
        self.reset();
        output
    }

    /// Lends the digest where the permutation leaves it, in the first four lanes of the state.
    #[inline(always)]
    fn finalize_reset_with_closure<FN: FnOnce(&Self::HashOutput)>(&mut self, closure: FN) {
        // SAFETY: without a destination `finish` writes the digest over the first four
        // lanes, which are initialised afterwards. `Bytes32` is 32 bytes aligned to a word
        // without invalid values, and the machine is little-endian. The borrow ends with the
        // closure, before the hasher is written again.
        let output = unsafe {
            self.finish(None);
            &*self.state.as_ptr().cast::<Bytes32>()
        };
        closure(output);
        self.reset();
    }
}

impl<F: KeccakF1600> Default for Keccak256Core<F> {
    #[inline(always)]
    fn default() -> Self {
        Self::const_new()
    }
}

impl<F: KeccakF1600> Clone for Keccak256Core<F> {
    #[inline(always)]
    fn clone(&self) -> Self {
        Self {
            state: self.state,
            filled: self.filled,
            valid: self.valid,
            permutation: PhantomData,
        }
    }
}

impl<F: KeccakF1600> core::fmt::Debug for Keccak256Core<F> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str("Keccak256 { ... }")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The `keccak` crate's permutation, behind every entry in its representation
    struct Reference;

    impl KeccakF1600 for Reference {
        fn permute(state: &mut [u64; LANES]) {
            for (lane, word) in state.iter_mut().enumerate() {
                *word ^= complement_of(lane);
            }
            keccak::f1600(state);
            for (lane, word) in state.iter_mut().enumerate() {
                *word ^= complement_of(lane);
            }
        }

        unsafe fn absorb_blocks(state: &mut [u64; LANES], data: *const u64, blocks: usize) {
            assert!(blocks >= 1 && data.is_aligned());
            for block in 0..blocks {
                for lane in 0..RATE_WORDS {
                    // SAFETY: the caller's contract
                    state[lane] ^= unsafe { data.add(block * RATE_WORDS + lane).read() };
                }
                Self::permute(state);
            }
        }

        unsafe fn absorb_first(state: *mut [u64; LANES], data: *const u64, blocks: usize) {
            // the all-zero state as stored; `state` is not read
            let mut fresh = [0u64; LANES];
            for (lane, word) in fresh.iter_mut().enumerate() {
                *word = complement_of(lane);
            }
            // SAFETY: the caller's contract
            unsafe {
                Self::absorb_blocks(&mut fresh, data, blocks);
                state.write(fresh);
            }
        }

        unsafe fn squeeze(state: *mut [u64; LANES], digest: *mut [u64; 4]) {
            // SAFETY: the caller's contract. The state is read whole before anything is
            // written, and then filled with a pattern: nothing may rely on it afterwards.
            unsafe {
                let mut permuted = state.read();
                Self::permute(&mut permuted);
                state.write([0x5555_5555_5555_5555; LANES]);
                for (lane, word) in permuted[..4].iter().enumerate() {
                    digest
                        .cast::<u64>()
                        .add(lane)
                        .write(word ^ complement_of(lane));
                }
            }
        }

        unsafe fn squeeze_short(lanes: *const [u64; SHORT_LANES], digest: *mut [u64; 4]) {
            let mut state = [0u64; LANES];
            // SAFETY: the caller's contract: nine initialised lanes, read before the digest
            // is written (the two may overlap). Under Miri the read fails if one is not.
            unsafe {
                state[..SHORT_LANES].copy_from_slice(&lanes.read());
                state[RATE_WORDS - 1] ^= 1 << 63;
                keccak::f1600(&mut state);
                for (lane, word) in state[..4].iter().enumerate() {
                    digest.cast::<u64>().add(lane).write(*word);
                }
            }
        }
    }

    type Hasher = Keccak256Core<Reference>;

    static SHARED: std::sync::Mutex<Hasher> = std::sync::Mutex::new(Hasher::const_new());

    const LONG: [usize; 8] = [407, 408, 409, 544, 680, 1000, 4096, 10007];
    const SPLIT: [usize; 12] = [1, 7, 8, 9, 31, 64, 135, 136, 137, 271, 272, 300];

    /// `len` bytes of a fixed pattern at an address that is `offset` modulo 8
    struct Input {
        words: Vec<u64>,
        offset: usize,
        len: usize,
    }

    impl Input {
        fn new(len: usize, offset: usize, seed: u64) -> Self {
            let mut words = vec![0u64; (offset + len) / 8 + 1];
            let mut x = seed.wrapping_mul(0x9e3779b97f4a7c15) | 1;
            for word in words.iter_mut() {
                x ^= x << 13;
                x ^= x >> 7;
                x ^= x << 17;
                *word = x;
            }
            Self { words, offset, len }
        }

        fn bytes(&self) -> &[u8] {
            // SAFETY: `offset + len` bytes are inside the allocation of the words.
            let bytes = unsafe {
                core::slice::from_raw_parts(self.words.as_ptr().cast::<u8>(), self.words.len() * 8)
            };
            let bytes = &bytes[self.offset..self.offset + self.len];
            assert_eq!(bytes.as_ptr() as usize % 8, self.offset % 8);
            bytes
        }
    }

    fn expected(input: &[u8]) -> [u8; 32] {
        <sha3::Keccak256 as sha3::Digest>::digest(input).into()
    }

    #[test]
    fn known_digests() {
        // Keccak-256 of the empty string and of "abc"
        assert_eq!(
            Hasher::digest([]).0,
            hex_literal::hex!("c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470")
        );
        assert_eq!(
            Hasher::digest(b"abc").0,
            hex_literal::hex!("4e03657aea45a94fc7d47ba826c8d667c0d1e6e33a64a036ec44f58fa12d6c45")
        );
    }

    #[test]
    fn every_length_and_alignment() {
        for len in (0..=300).chain(LONG) {
            for offset in 0..8 {
                let input = Input::new(len, offset, len as u64);
                let input = input.bytes();
                let expected = expected(input);
                assert_eq!(Hasher::digest(input).0, expected, "digest {len} {offset}");
                let mut hasher = Hasher::new();
                hasher.update(input);
                assert_eq!(hasher.finalize().0, expected, "update {len} {offset}");
            }
        }
    }

    #[test]
    fn split_updates() {
        for len in SPLIT.into_iter().chain([409, 1000]) {
            for offset in [0, 1, 3, 4, 7] {
                let input = Input::new(len, offset, 77 + len as u64);
                let input = input.bytes();
                let expected = expected(input);
                for split in 0..=len {
                    let mut hasher = Hasher::new();
                    hasher.update(&input[..split]);
                    hasher.update(&input[split..]);
                    assert_eq!(hasher.finalize().0, expected, "{len} {offset} {split}");
                }
            }
        }
    }

    /// Every public path at every length of a single block and a little more, with the hasher
    /// reused: small enough for Miri, which reports a read of a lane that was never written.
    #[test]
    fn every_path_of_a_short_hash() {
        let step = if cfg!(miri) { 7 } else { 1 };
        let mut reused = Hasher::new();
        for len in (0..=140).step_by(step).chain([32, 64, 65, 135, 136]) {
            for offset in [0, 1, 4] {
                let input = Input::new(len, offset, 11 + len as u64);
                let input = input.bytes();
                let expected = expected(input);
                assert_eq!(Hasher::digest(input).0, expected, "digest {len} {offset}");
                let mut hasher = Hasher::new();
                hasher.update(input);
                assert_eq!(hasher.finalize().0, expected, "finalize {len} {offset}");
                reused.update(input);
                assert_eq!(reused.finalize_reset().0, expected, "reset {len} {offset}");
                let (head, tail) = input.split_at(len / 2);
                reused.update(head);
                reused.update(tail);
                let mut seen = None;
                reused.finalize_reset_with_closure(|digest| seen = Some(digest.0));
                assert_eq!(seen, Some(expected), "closure {len} {offset}");
            }
        }
    }

    #[test]
    fn many_small_updates() {
        // pieces of every length up to 23 at drifting alignments and state offsets
        let input = Input::new(5000, 5, 3);
        let input = input.bytes();
        let mut hasher = Hasher::new();
        let (mut at, mut piece) = (0, 0);
        while at < input.len() {
            let end = core::cmp::min(at + piece % 24, input.len());
            hasher.update(&input[at..end]);
            at = end;
            piece += 1;
        }
        assert_eq!(hasher.finalize().0, expected(input));
    }

    #[test]
    fn finalize_reset_reuses_the_hasher() {
        let mut hasher = Hasher::new();
        for len in [0, 1, 135, 136, 137, 300, 32, 1000, 64] {
            let input = Input::new(len, len % 8, 5);
            let (head, tail) = input.bytes().split_at(len / 3);
            hasher.update(head);
            hasher.update(tail);
            assert_eq!(hasher.finalize_reset().0, expected(input.bytes()), "{len}");
        }
    }

    #[test]
    fn closure_lends_the_digest_in_place() {
        let mut hasher = Hasher::new();
        for len in [0, 32, 64, 136, 137, 1000] {
            let input = Input::new(len, 0, 9);
            hasher.update(input.bytes());
            let state = hasher.state.as_ptr() as usize;
            let mut seen = None;
            hasher.finalize_reset_with_closure(|digest| {
                assert_eq!(
                    digest as *const Bytes32 as usize, state,
                    "not lent in place"
                );
                seen = Some(digest.0);
            });
            assert_eq!(seen, Some(expected(input.bytes())), "{len}");
        }
        // and the hasher is fresh afterwards
        assert_eq!(hasher.finalize_reset().0, expected(&[]));
    }

    #[test]
    fn const_new_in_a_static() {
        let mut hasher = SHARED.lock().unwrap();
        hasher.update(b"abc");
        assert_eq!(hasher.finalize_reset().0, expected(b"abc"));
        let fresh = Hasher::const_new();
        assert_eq!((fresh.filled, fresh.valid), (0, 0));
        assert_eq!(fresh.clone().finalize().0, Hasher::default().finalize().0);
    }
}
